; ---- Subroutine: sys.die ----

    ALIGN 2

sys.die:
            moveq   #0,d0
            move.w  12(a5),d0
            lea      .alert(pc),a1
            lea      .alert_limit(pc),a3
            move.w   #20,(a1)+
            move.b   #16,(a1)+
            lea      .prefix(pc),a2
.copy_prefix:
            move.b   (a2)+,d1
            beq.s    .copy_code
            move.b   d1,(a1)+
            bra.s    .copy_prefix
.copy_code:
            move.w  12(a5),d2
            moveq    #3,d4
.copy_code_digit:
            move.w   d2,d3
            lsr.w    #8,d3
            lsr.w    #4,d3
            andi.w   #$000f,d3
            cmpi.w   #10,d3
            bcs.s    .copy_code_number
            addi.w   #'A'-10,d3
            bra.s    .copy_code_store
.copy_code_number:
            addi.w   #'0',d3
.copy_code_store:
            move.b   d3,(a1)+
            lsl.w    #4,d2
            dbra     d4,.copy_code_digit
            clr.b    (a1)+
            move.b   #1,(a1)+
            move.w   #20,(a1)+
            move.b   #32,(a1)+
.copy_message:
            move.l   8(a5),a0
.copy_message_loop:
            cmpa.l   a3,a1
            bhi.s    .message_full
            move.b   (a0)+,d1
            move.b   d1,(a1)+
            bne.s    .copy_message_loop
            clr.b    (a1)
            bra.s    .display
.message_full:
            subq.l   #1,a1
            clr.b    (a1)
            clr.b    1(a1)
.display:
            moveq   #48,d1
            movea.l  sys.IntuitionBase,a6
            lea      .alert(pc),a0
            jsr      -90(a6)
            moveq   #0,d0
            move.w  12(a5),d0
            jmp      sys.exit

            even
.alert:
            ds.b     158
.alert_limit:
            ds.b     2
.alert_end:
.prefix:
            dc.b     "PROGRAM DIED code $",0
            ; !notreached!
; End of subroutine: sys.die


; ---- Subroutine: sys.memset ----
    ALIGN 2

sys.memset:
            movea.l  d0,a0
            tst.w    d1
            beq      .done
            tst.b    d2
            beq      sys.memclear       ; tail-call: value==0

            ; save fill byte zero-extended
            moveq    #0,d3
            move.b   d2,d3

            ; align address to even for word/longword transfers
            move.l   a0,d0
            btst     #0,d0
            beq      .aligned
            move.b   d3,(a0)+
            subq.l   #1,d1
            beq      .done

.aligned:
            ; expand fill byte to all byte positions in d3
            move.l   d3,d0
            lsl.l    #8,d0
            or.l     d0,d3
            move.l   d3,d0
            swap     d0
            or.l     d0,d3

            ; longword fill (4 bytes per iteration)
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            lsr.l    #2,d0
            beq      .bytes
            subq.w   #1,d0
.loop_l:
            move.l   d3,(a0)+
            dbra     d0,.loop_l

            ; remaining bytes (0-3)
.bytes:
            and.w    #3,d1
            beq      .done
            subq.w   #1,d1
.loop_b:
            move.b   d3,(a0)+
            dbra     d1,.loop_b
.done:
            rts
; End of subroutine: sys.memset


; ---- Subroutine: sys.memclear ----
    ALIGN 2

sys.memclear:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            beq      .done

            ; align to even for word/longword access
            move.l   a0,d1
            btst     #0,d1
            beq      .compute
            clr.b    (a0)+
            subq.l   #1,d0
            beq      .done

.compute:
            move.l   d0,d1
            move.l   d1,d2
            and.w    #31,d2          ; d2 = tail bytes after 32-byte blocks
            lsr.l    #5,d1           ; d1 = number of 32-byte blocks
            move.l   d2,a2           ; a2 = tail bytes
            movea.l  d1,a1           ; a1 = block count (save before zeroing regs)

            ; point a0 past the last byte, so we can decrement with movem
            move.l   d1,d3
            lsl.l    #5,d3
            adda.l   d3,a0           ; a0 = end address
            movea.l  a0,a4           ; a4 = end address; the movem loop leaves a0 back at the start

            ; zero all data registers except d7 (d7 will be the loop counter, not in movem)
            move.l   d1,d7           ; d7 = block count (save before zeroing)
            moveq    #0,d0
            move.l   d0,d1
            move.l   d0,d2
            move.l   d0,d3
            move.l   d0,d4
            move.l   d0,d5
            move.l   d0,d6
            movea.l  d0,a1           ; also zero a1 (part of movem)

            ; bulk clear: 32 bytes per movem (d0-d6=28 bytes + a1=4 bytes), decrementing a0
            subq.w   #1,d7
            bmi      .tail
.loop_m:
            movem.l  d0-d6/a1,-(a0)
            dbra     d7,.loop_m

.tail:
            movea.l  a4,a0           ; a0 = end of the bulk region, where the tail bytes belong
            movea.l  a2,a3
            move.l   a3,d0           ; copy to data reg for shift/btst
            beq      .done
            move.l   d0,d1
            lsr.l    #2,d1           ; d1 = longwords in tail
            beq      .tail_words
            subq.l   #1,d1
.loop_l:
            clr.l    (a0)+
            subq.l   #1,d1
            bpl      .loop_l

.tail_words:
            btst     #1,d0
            beq      .tail_byte
            clr.w    (a0)+

.tail_byte:
            btst     #0,d0
            beq      .done
            clr.b    (a0)+
.done:
            rts
; End of subroutine: sys.memclear


; ---- Subroutine: sys.memsetw ----
    ALIGN 2

sys.memsetw:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numwords (zero-extended)
            beq      .done
            move.w   d2,d1           ; d1 = fill word value

            ; Create longword fill pattern: d1:d1
            move.w   d1,d2
            swap     d2
            move.w   d1,d2           ; d2 = d1 : d1

            ; longword fill (2 words at a time)
            move.l   d0,d3
            lsr.l    #1,d3           ; d3 = numwords / 2
            beq      .odd_word
            subq.w   #1,d3
.loop_l:
            move.l   d2,(a0)+
            dbra     d3,.loop_l

.odd_word:
            btst     #0,d0
            beq      .done
            move.w   d1,(a0)+

.done:
            rts
; End of subroutine: sys.memsetw


; ---- Subroutine: sys.memsetl ----
    ALIGN 2

sys.memsetl:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numlongs (zero-extended)
            beq      .done

            ; longword fill
            subq.w   #1,d0
.loop_l:
            move.l   d2,(a0)+
            dbra     d0,.loop_l

.done:
            rts
; End of subroutine: sys.memsetl


